mapper.select:
SELECT pp.id as id, pp.code as code, pp.dict_platform as dictPlatform, pp.shop_id as shopId, pp.package_no as packageNo, pp.package_status as packageStatus, pp.is_handover_download as isHandoverDownload, pp.box_num as boxNum, pp.delivery_warehouse_id as deliveryWarehouseId, pp.delivery_warehouse_name as deliveryWarehouseName, pp.print_handover_status as printHandoverStatus, pp.print_order_status as printOrderStatus, pp.create_time as createTime, pp.create_user_name as createUserName FROM package_plan pp LEFT JOIN package_plan_detail ppd on ppd.main_id = pp.id and ppd.is_deleted=FALSE WHERE ${params.sqlMap.default} and pp.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC

SELECT pp.id as id, pp.code as code, pp.dict_platform as dictPlatform, pp.shop_id as shopId, pp.package_no as packageNo, pp.package_status as packageStatus, pp.is_handover_download as isHandoverDownload, pp.box_num as boxNum, pp.delivery_warehouse_id as deliveryWarehouseId, pp.delivery_warehouse_name as deliveryWarehouseName, pp.print_handover_status as printHandoverStatus, pp.print_order_status as printOrderStatus, pp.create_time as createTime, pp.create_user_name as createUserName, ppd.so_code as soCode, ppd.so_id as soId, ppd.logistics_channel_id as logisticsChannelId, ppd.logistics_channel_name as logisticsChannelName, ppd.track_no as trackNo, ppd.transport_no as transportNo, ppd.barcode as barcode FROM package_plan pp LEFT JOIN package_plan_detail ppd on ppd.main_id = pp.id and ppd.is_deleted=FALSE WHERE ${params.sqlMap.default} and pp.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC
